sql.q1:
```
SELECT count(*) FROM issues WHERE state = 'open' AND (lower(title) LIKE '%security%' OR lower(body) LIKE '%security%');
```

sql.q2:
```
SELECT count(*) FROM issues WHERE is_pr = 1;
```

sql.q3:
```
SELECT sum(comments) FROM issues WHERE state = 'closed';
```

sql.q4:
```
SELECT user || ' ' || count(*) FROM issues WHERE is_pr = 1 GROUP BY user ORDER BY count(*) DESC LIMIT 1;
```

sql.q5:
```
SELECT group_concat(number, ',') FROM (SELECT number FROM issues WHERE state = 'open' AND is_pr = 0 AND comments > 5 ORDER BY number);
```

sql.q6:
```
SELECT count(DISTINCT j.value) FROM issues, json_each(issues.labels) AS j;
```

sql.q7:
```
SELECT count(*) FROM issues WHERE state = 'open' AND EXISTS (SELECT 1 FROM json_each(issues.labels) WHERE value = 'bug');
```

sql.q9:
```
SELECT count(*) FROM (SELECT user FROM issues WHERE is_pr = 1 INTERSECT SELECT user FROM issues WHERE is_pr = 0);
```

sql.q10:
```
SELECT round(avg(comments), 2) FROM issues WHERE state = 'open' AND is_pr = 0;
```
